--- clean/crates/crypto/circuits/src/group/fixed_inspection.rs
+++ overlay/crates/crypto/circuits/src/group/fixed_inspection.rs
@@ -0,0 +1,185 @@
+//! Bounded read-only observation of the spend randomizer's ascending fixed loop.
+use super::{Point, Scalar};
+use crate::scalar::inspection::Observed;
+use commonware_cryptography::zk::circuit::{BoolVar, CircuitIdx, Var};
+use std::{cell::RefCell, marker::PhantomData, rc::Rc};
+
+#[derive(Clone, PartialEq, Eq)]
+pub struct Window {
+    pub bits: [CircuitIdx; 2],
+    /// Current native base, twice, triple, next native base.
+    pub table: [[Observed; 2]; 4],
+    /// Accumulator before, selected digit, accumulator after.
+    pub points: [[Observed; 2]; 3],
+    /// Actual add products xx, yy, (x+y)(u+v), xx*yy, before native d scaling.
+    pub arithmetic: [Observed; 4],
+    /// Existing numerator x/y, denominator x/y, quotient x/y.
+    pub quotient: [Observed; 6],
+}
+#[derive(Clone, PartialEq, Eq)]
+pub struct Report {
+    pub window_start: usize,
+    pub window_count: usize,
+    pub randomizer: Observed,
+    pub generator: [Observed; 2],
+    pub bits: Vec<CircuitIdx>,
+    pub windows: Vec<Window>,
+    pub output: [Observed; 2],
+}
+struct State {
+    start: usize,
+    count: usize,
+    active: bool,
+    calls: usize,
+    current: Option<usize>,
+    visited: usize,
+    randomizer: Option<Observed>,
+    generator: Option<[Observed; 2]>,
+    bits: Vec<CircuitIdx>,
+    windows: Vec<Window>,
+    quotient: Option<[Observed; 6]>,
+    arithmetic: Option<[Observed; 4]>,
+    output: Option<[Observed; 2]>,
+}
+thread_local! { static STATE: RefCell<Option<State>> = const { RefCell::new(None) }; }
+pub struct Capture { _thread: PhantomData<Rc<()>> }
+impl Drop for Capture { fn drop(&mut self) { STATE.with(|s| *s.borrow_mut() = None); } }
+pub fn begin(start: usize, count: usize) -> anyhow::Result<Capture> {
+    anyhow::ensure!(start < 126 && (1..=16).contains(&count) && start + count <= 126,
+        "fixed window capture bounds");
+    STATE.with(|cell| {
+        let mut cell = cell.borrow_mut();
+        anyhow::ensure!(cell.is_none(), "nested fixed capture");
+        *cell = Some(State { start, count, active: false, calls: 0, current: None,
+            visited: 0, randomizer: None, generator: None, bits: Vec::new(),
+            windows: Vec::with_capacity(count), quotient: None, arithmetic: None, output: None });
+        Ok(Capture { _thread: PhantomData })
+    })
+}
+pub struct Scope { _thread: PhantomData<Rc<()>> }
+impl Drop for Scope {
+    fn drop(&mut self) { STATE.with(|s| if let Some(s) = s.borrow_mut().as_mut() { s.active = false; }); }
+}
+fn observed(v: &Var<'_, Scalar>) -> Observed {
+    match v.inspect_circuit_idx() {
+        Some(index) => Observed::Source(index),
+        None => Observed::Native(v.inspect_native().expect("invalid fixed observed variable").clone()),
+    }
+}
+fn point(v: &Point<Var<'_, Scalar>>) -> [Observed; 2] { [observed(&v.x), observed(&v.y)] }
+fn native(v: &Point<Scalar>) -> [Observed; 2] {
+    [Observed::Native(v.x.clone()), Observed::Native(v.y.clone())]
+}
+pub(crate) fn spend_scope(randomizer: &Var<'_, Scalar>) -> Option<Scope> {
+    STATE.with(|cell| {
+        let mut cell = cell.borrow_mut();
+        let state = cell.as_mut()?;
+        assert!(!state.active && state.calls == 0, "duplicate fixed spend scope");
+        state.active = true;
+        state.calls += 1;
+        state.randomizer = Some(observed(randomizer));
+        Some(Scope { _thread: PhantomData })
+    })
+}
+pub(super) fn begin_loop(base: &Point<Scalar>, bits: &[BoolVar<'_, Scalar>]) {
+    STATE.with(|cell| if let Some(state) = cell.borrow_mut().as_mut().filter(|s| s.active) {
+        assert!(state.generator.is_none() && bits.len() == 252, "fixed loop shape");
+        state.generator = Some(native(base));
+        state.bits = bits.iter().map(|bit| bit.var().inspect_circuit_idx()
+            .expect("fixed bit must be a source")).collect();
+    });
+}
+pub(super) fn begin_window(index: usize) {
+    STATE.with(|cell| if let Some(state) = cell.borrow_mut().as_mut().filter(|s| s.active) {
+        assert!(index == state.visited && state.current.is_none(), "fixed iterator order");
+        state.current = Some(index);
+        state.visited += 1;
+    });
+}
+pub(super) fn selected() -> bool {
+    STATE.with(|cell| cell.borrow().as_ref().is_some_and(|s| s.active &&
+        s.current.is_some_and(|i| s.start <= i && i < s.start + s.count)))
+}
+pub(super) fn quotient(values: [&Var<'_, Scalar>; 6]) {
+    if !selected() { return; }
+    STATE.with(|cell| {
+        let mut cell = cell.borrow_mut();
+        let state = cell.as_mut().expect("fixed state");
+        assert!(state.quotient.is_none(), "duplicate fixed quotient");
+        state.quotient = Some(values.map(observed));
+    });
+}
+pub(super) fn arithmetic(values: [&Var<'_, Scalar>; 4]) {
+    if !selected() { return; }
+    STATE.with(|cell| {
+        let mut cell = cell.borrow_mut();
+        let state = cell.as_mut().expect("fixed state");
+        assert!(state.arithmetic.is_none(), "duplicate fixed arithmetic");
+        state.arithmetic = Some(values.map(observed));
+    });
+}
+pub(super) fn finish_window(base: &Point<Scalar>, twice: &Point<Scalar>, triple: &Point<Scalar>,
+    next_base: &Point<Scalar>, input: &Point<Var<'_, Scalar>>, selected_point: &Point<Var<'_, Scalar>>,
+    output: &Point<Var<'_, Scalar>>) {
+    STATE.with(|cell| if let Some(state) = cell.borrow_mut().as_mut().filter(|s| s.active) {
+        let index = state.current.take().expect("fixed window before begin");
+        if state.start <= index && index < state.start + state.count {
+            assert!(state.windows.len() < state.count, "fixed window capture overflow");
+            state.windows.push(Window { bits: [state.bits[2 * index], state.bits[2 * index + 1]],
+                table: [native(base), native(twice), native(triple), native(next_base)],
+                points: [point(input), point(selected_point), point(output)],
+                arithmetic: state.arithmetic.take().expect("missing fixed arithmetic"),
+                quotient: state.quotient.take().expect("missing fixed quotient") });
+        }
+    });
+}
+pub(super) fn finish_loop(output: &Point<Var<'_, Scalar>>) {
+    STATE.with(|cell| if let Some(state) = cell.borrow_mut().as_mut().filter(|s| s.active) {
+        assert!(state.visited == 126 && state.current.is_none() && state.output.is_none(),
+            "fixed loop finish shape");
+        state.output = Some(point(output));
+    });
+}
+pub fn take() -> anyhow::Result<Report> {
+    STATE.with(|cell| {
+        let mut cell = cell.borrow_mut();
+        let state = cell.as_mut().ok_or_else(|| anyhow::anyhow!("fixed capture absent"))?;
+        anyhow::ensure!(!state.active && state.calls == 1 && state.visited == 126 &&
+            state.windows.len() == state.count && state.quotient.is_none() && state.arithmetic.is_none(),
+            "fixed capture occurrence/completion mismatch");
+        let report = Report { window_start: state.start, window_count: state.count,
+            randomizer: state.randomizer.take().ok_or_else(|| anyhow::anyhow!("fixed randomizer absent"))?,
+            generator: state.generator.take().ok_or_else(|| anyhow::anyhow!("fixed generator absent"))?,
+            bits: std::mem::take(&mut state.bits), windows: std::mem::take(&mut state.windows),
+            output: state.output.take().ok_or_else(|| anyhow::anyhow!("fixed output absent"))? };
+        anyhow::ensure!(report.bits.len() == 252, "fixed bit count");
+        for (offset, window) in report.windows.iter().enumerate() {
+            let i = 2 * (report.window_start + offset);
+            anyhow::ensure!(window.bits == [report.bits[i], report.bits[i + 1]] &&
+                window.quotient[4..] == window.points[2], "fixed captured role mismatch");
+            if offset > 0 {
+                let previous = &report.windows[offset - 1];
+                anyhow::ensure!(previous.points[2] == window.points[0] &&
+                    previous.table[3] == window.table[0], "fixed captured window chain mismatch");
+            }
+        }
+        Ok(report)
+    })
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    #[test]
+    fn bounds_exclusivity_and_unfinished_capture_refuse() {
+        for (start, count) in [(126, 1), (0, 0), (0, 17), (125, 2)] {
+            assert!(begin(start, count).is_err());
+        }
+        let capture = begin(110, 16).unwrap();
+        assert!(begin(0, 1).is_err());
+        assert!(take().is_err());
+        drop(capture);
+        let _capture = begin(0, 1).unwrap();
+        assert!(!selected());
+    }
+}
